declare(strict_types=1);
function l80_need(bool $x,string $w):void{if(!$x)throw new RuntimeException($w);}
function l80_json(mixed $v):string{return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);}
function l80_hash(mixed $v):string{return hash('sha256',l80_json($v));}
function l80_write(string $p,array $v):string{$raw=l80_json($v)."\n";$f=fopen($p,'xb');l80_need(is_resource($f),'open');try{l80_need(fwrite($f,$raw)===strlen($raw)&&fflush($f),'write');if(function_exists('fsync'))l80_need(fsync($f),'sync');}finally{fclose($f);}return hash('sha256',$raw);}
function l80_rows(PDO $db,string $sql,array $p=[]):array{$s=$db->prepare($sql);$s->execute(array_values($p));return$s->fetchAll(PDO::FETCH_ASSOC)?:[];}
function l80_star(array $h):?int{foreach(['star','starLName','category']as$k)if(isset($h[$k])&&preg_match('/([1-5])/u',(string)$h[$k],$m))return(int)$m[1];return null;}
function l80_catalogs(string $dir,array $safe):array{$files=['Катар'=>['raw-catalog-a2dc2cf490.json','2a74c0711c02105c0a636119f86e3e1882ad29bc2bbd73f1be513cf64155eb6a'],'Маврикий'=>['raw-catalog-490f3ae3b6.json','3278cf955d7fd87c9a5694783b1434c23c8ce94717b9b68dc86e5ecbe7b692ce'],'Египет'=>['raw-catalog-dfd0573e11.json','feecbab9f7cc6a6bb093ab5a744b2a843e79be6e4f570bd80b234661ac8b5755'],'Вьетнам'=>['raw-catalog-ed0216a76e.json','05d8492c2efd76f003a11bbcce5a2d8de328c59c204b3768ee9d071bc930447b'],'Индия'=>['raw-catalog-095b0b9746.json','8409bc681cb9976c59956adc91ffd10db87182e0f21d97cc170e65a5cae5f8ec'],'Тунис'=>['raw-catalog-44073d4b69.json','41431f0053319ec26739d14ece07be863f34c1f4836078bd8d6c284818ea986c'],'ОАЭ'=>['raw-catalog-9c8cdbecb6.json','4a7394a30208e2f942549b914ce989e68d32f0914279434900f723b4a5d27dd2'],'Казахстан'=>['raw-catalog-b41ea69d28.json','00832b04a4a256ec4fe2070efa29148112f82b78feb4cab29b2945e28dfe660d']];$out=[];foreach($files as$c=>[$f,$h]){$p=$dir.'/'.$f;l80_need(is_file($p)&&hash_file('sha256',$p)===$h,'catalog_'.$c);$j=json_decode((string)file_get_contents($p),true,64,JSON_THROW_ON_ERROR);foreach((array)$j['HOTELS']as$x){$id=(string)($x['id']??'');if(isset($safe[$id]))$out[$id]=['country'=>$c,'hash'=>$h,'hotel'=>$x];}}return$out;}
